const uint8_t *menu_font_glyph(uint32_t codepoint)
{
    int lo = 0;
    int hi = (int)(sizeof(GLYPHS) / sizeof(GLYPHS[0])) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        uint32_t value = GLYPHS[mid].codepoint;
        if (value == codepoint) return GLYPHS[mid].bitmap;
        if (value < codepoint) lo = mid + 1;
        else hi = mid - 1;
    }
    return NULL;
}
